{
  "name": "GPS定位接收器",
  "name_en": "GPS Receiver",
  "manufacturer": "",
  "description": "一种通过串口输出 NMEA 语句的 GPS 接收器，用于测量车辆、机器人或移动实验平台的地理位置。实验中可用于定位、轨迹记录，以及将经纬度转换为平面位置坐标以支持导航与路径分析。",
  "description_en": "A GPS receiver that outputs NMEA sentences over a serial connection to measure the geographic position of a vehicle, robot, or other mobile experimental platform. In lab use, it supports positioning, trajectory logging, and conversion of latitude/longitude into planar position coordinates for navigation and path analysis.",
  "tag_hints": [
    "GPS positioning",
    "NMEA serial",
    "geolocation",
    "robot navigation",
    "trajectory logging",
    "mobile platform tracking"
  ],
  "actions": [
    {
      "action_name": "auto-run_once",
      "description": "处理一组输入的 NMEA 语句并转换为位置结果。",
      "description_en": "Process a set of input NMEA sentences and convert them into a position result."
    },
    {
      "action_name": "auto-run",
      "description": "读取 GPS 接收器的当前数据并输出当前位置。",
      "description_en": "Read the current data from the GPS receiver and output the current position."
    },
    {
      "action_name": "auto-run_threaded",
      "description": "返回后台持续更新的最近一次有效位置。",
      "description_en": "Return the most recent valid position updated continuously in the background."
    },
    {
      "action_name": "auto-update",
      "description": "持续从 GPS 接收器读取 NMEA 数据并更新最新位置。",
      "description_en": "Continuously read NMEA data from the GPS receiver and update the latest position."
    },
    {
      "action_name": "auto-shutdown",
      "description": "停止定位读取并关闭设备连接。",
      "description_en": "Stop position acquisition and close the device connection."
    }
  ]
}

